// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address recipient, uint256 funding, uint256 amount) public {
        vm.assume(recipient != address(this));
        vm.assume(recipient != address(0));
        funding = bound(funding, 1, 1000 ether);
        amount = bound(amount, 1, funding);
        vm.deal(address(c), funding);

        uint256 recipientBefore = recipient.balance;
        vm.prank(address(this));
        c.withdrawAll(recipient);
        uint256 recipientAfter = recipient.balance;

        assertTrue(recipientAfter == recipientBefore + funding && address(c).balance == 0);
    }
}
